module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;

    // Assign complemented outputs
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // D Flip-Flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // Reset condition: all flip-flops start at 0
        // In simulation/synthesis with initial reset, this block captures the intent.
        // For a pure register without explicit reset pin, initial values are set via 'initial' block
        // or configuration. Here we use a blocking assignment style for clarity, but
        // non-blocking is standard for clocked blocks.
        // We assume asynchronous active-low reset is not present, so we rely on initial block.
        // To strictly follow "initially reset to zero", we use an initial block below.
    end

    // Initial block to set reset state (simulates power-up reset)
    initial begin
        q0 = 1'b0;
        q1 = 1'b0;
        q2 = 1'b0;
    end

    // Flip-Flop 0: D input is XOR of x and its own output (q0)
    always @(posedge clk) begin
        q0 <= x ^ q0;
    end

    // Flip-Flop 1: D input is AND of x and complemented output of q1
    always @(posedge clk) begin
        q1 <= x & q1_n;
    end

    // Flip-Flop 2: D input is OR of x and complemented output of q2
    always @(posedge clk) begin
        q2 <= x | q2_n;
    end

    // Three-input NOR gate: inputs are q0, q1, q2
    // Output z is high only when all three flip-flop outputs are low
    assign z = ~(q0 | q1 | q2);

endmodule

