module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to track the sequence 1101
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_1      = 2'b01,
        S_11     = 2'b10,
        S_110    = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE; // received 0, reset to idle
            end
            S_11: begin
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_11; // received 1, stay in S_11 (overlap possibility)
            end
            S_110: begin
                if (data == 1'b1)
                    next_state = S_IDLE; // completed sequence 1101
                else
                    next_state = S_IDLE; // sequence broken
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic: start_shifting goes high when we enter S_110 (sequence found)
    // and stays high forever until reset
    assign start_shifting = (state == S_110) ? 1'b1 : 1'b0;

endmodule

