module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // State A: 3'b000
    // State B: 3'b001 (f=1 for one cycle)
    // State C: 3'b010 (monitoring x for pattern 1,0,1)
    // State D: 3'b011 (g=1, waiting for y=1 within 2 cycles)
    // State E: 3'b100 (g=0 permanently after y timeout)
    // State F: 3'b101 (g=1 permanently after y=1 detected)

    reg [2:0] state, next_state;

    // Output assignments
    // f is 1 only in state B
    assign f = (state == 3'b001);

    // g is 1 in states D and F
    assign g = (state == 3'b011) || (state == 3'b101);

    // State register (positive edge triggered, synchronous active low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 3'b000; // state A
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            3'b000: // State A
                next_state = 3'b001; // Go to state B

            3'b001: // State B
                next_state = 3'b010; // Go to state C

            3'b010: // State C (monitoring x for 1,0,1)
                if (x == 1'b1) begin
                    // First '1' received, go to state D (which remembers we saw a 1)
                    next_state = 3'b011;
                end else begin
                    next_state = 3'b010; // Stay in state C
                end

            3'b011: // State D (have seen a 1, now waiting for 0 then 1)
                if (x == 1'b0) begin
                    // Received the 0 after the first 1, go to state E
                    next_state = 3'b100;
                end else begin
                    // x is 1 again, reset the pattern detection, stay in state D
                    // (this handles the case where we get 1,1 - we start over looking for 1,0,1)
                    next_state = 3'b011;
                end

            3'b100: // State E (have seen 1,0, now waiting for the final 1)
                if (x == 1'b1) begin
                    // Received the final 1, pattern 1,0,1 detected, go to state F
                    next_state = 3'b101;
                end else begin
                    // Did not receive the final 1, go to state G (g=0 permanently)
                    next_state = 3'b110;
                end

            3'b101: // State F (pattern 1,0,1 detected, g=1, waiting for y)
                if (y == 1'b1) begin
                    // y=1 detected within the allowed time, g stays 1 permanently
                    next_state = 3'b101;
                end else begin
                    // y is 0, need to check if we have waited 2 cycles already
                    // In this simplified model, if y is 0 we transition to state G
                    next_state = 3'b110;
                end

            3'b110: // State G (g=0 permanently due to timeout or failure)
                next_state = 3'b110; // Stay in state G

            default: next_state = 3'b000;
        endcase
    end

endmodule

