module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Fall duration counter
    typedef logic [5:0] count_t;  // 0 to 63
    count_t fall_count, next_fall_count;

    // Outputs (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state     <= WALK_LEFT;
            fall_count <= 0;
        end else begin
            state     <= next_state;
            fall_count <= next_fall_count;
        end
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;
        next_fall_count = fall_count;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall immediately when ground disappears
                    next_state = FALLING;
                    next_fall_count = 1;
                end else if (dig) begin
                    // Start digging when walking on ground
                    next_state = DIGGING;
                    next_fall_count = 0;
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped
                    if (bump_left && !bump_right)
                        next_state = WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_LEFT;
                    else
                        // Bumped on both sides - still switch
                        next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                end
                // else stay WALK_LEFT
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_count = 1;
                end else if (dig) begin
                    next_state = DIGGING;
                    next_fall_count = 0;
                end else if (bump_left || bump_right) begin
                    if (bump_left && !bump_right)
                        next_state = WALK_LEFT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_RIGHT;
                    else
                        next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                end
            end

            FALLING: begin
                // Count falling cycles
                if (fall_count >= 20) begin
                    // Already fallen >= 20 cycles
                    if (ground) begin
                        // Ground reappears: check splatter condition
                        if (fall_count > 20) begin
                            // Fell for more than 20 cycles -> splatter
                            next_state = SPLATTERED;
                            next_fall_count = 0;
                        end else begin
                            // fall_count == 20: "more than 20 cycles" means >20,
                            // so exactly 20 cycles does NOT splatter.
                            // Resume walking in same direction.
                            // Determine original direction from state.
                            // Since we were WALK_LEFT or WALK_RIGHT before fall,
                            // and we resume in same direction:
                            next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
                            next_fall_count = 0;
                        end
                    end else begin
                        // Ground still absent -> stay falling, increment counter
                        next_fall_count = fall_count + 1;
                    end
                end else begin
                    // fall_count < 20
                    if (ground) begin
                        // Ground reappears within < 20 cycles -> resume walking
                        next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
                        next_fall_count = 0;
                    end else begin
                        // Still falling, stay in FALLING, increment counter
                        next_fall_count = fall_count + 1;
                    end
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side while digging - fall
                    next_state = FALLING;
                    next_fall_count = 1;
                end else if (bump_left || bump_right) begin
                    // Being bumped while digging has no effect
                    // Stay digging, counter stays 0
                end else begin
                    // Continue digging
                end
                // If ground=1 and no bump, stay DIGGING
            end

            SPLATTERED: begin
                // Forever stuck - stay splattered
                next_state = SPLATTERED;
                next_fall_count = 0;
            end
        endcase
    end

endmodule
